CREATE TABLE default.beacon_api_eth_v1_beacon_blob_local\n(\n    `event_date_time` DateTime64(3) COMMENT \'When the sentry received the event from a beacon node\' CODEC(DoubleDelta, ZSTD(1)),\n    `slot` UInt32 COMMENT \'Slot number in the beacon block\' CODEC(DoubleDelta, ZSTD(1)),\n    `slot_start_date_time` DateTime COMMENT \'The wall clock time when the slot started\' CODEC(DoubleDelta, ZSTD(1)),\n    `epoch` UInt32 COMMENT \'The epoch number\' CODEC(DoubleDelta, ZSTD(1)),\n    `epoch_start_date_time` DateTime COMMENT \'The wall clock time when the epoch started\' CODEC(DoubleDelta, ZSTD(1)),\n    `block_root` FixedString(66) COMMENT \'The beacon block root hash\' CODEC(ZSTD(1)),\n    `block_parent_root` FixedString(66) COMMENT \'The beacon block parent root hash\' CODEC(ZSTD(1)),\n    `proposer_index` UInt32 COMMENT \'The validator index of the block proposer\' CODEC(ZSTD(1)),\n    `blob_index` UInt64 COMMENT \'The index of the blob within the block\' CODEC(ZSTD(1)),\n    `kzg_commitment` FixedString(98) COMMENT \'The KZG commitment of the blob\' CODEC(ZSTD(1)),\n    `versioned_hash` FixedString(66) COMMENT \'The versioned hash derived from the KZG commitment (key for joining with execution_engine_get_blobs)\' CODEC(ZSTD(1)),\n    `meta_client_name` LowCardinality(String) COMMENT \'Name of the client that generated the event\',\n    `meta_client_id` String COMMENT \'Unique Session ID of the client that generated the event. This changes every time the client is restarted.\' CODEC(ZSTD(1)),\n    `meta_client_version` LowCardinality(String) COMMENT \'Version of the client that generated the event\',\n    `meta_client_implementation` LowCardinality(String) COMMENT \'Implementation of the client that generated the event\',\n    `meta_client_os` LowCardinality(String) COMMENT \'Operating system of the client that generated the event\',\n    `meta_client_ip` Nullable(IPv6) COMMENT \'IP address of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_client_geo_city` LowCardinality(String) COMMENT \'City of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_client_geo_country` LowCardinality(String) COMMENT \'Country of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_client_geo_country_code` LowCardinality(String) COMMENT \'Country code of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_client_geo_continent_code` LowCardinality(String) COMMENT \'Continent code of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_client_geo_longitude` Nullable(Float64) COMMENT \'Longitude of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_client_geo_latitude` Nullable(Float64) COMMENT \'Latitude of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_client_geo_autonomous_system_number` Nullable(UInt32) COMMENT \'Autonomous system number of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_client_geo_autonomous_system_organization` Nullable(String) COMMENT \'Autonomous system organization of the client that generated the event\' CODEC(ZSTD(1)),\n    `meta_network_id` Int32 COMMENT \'Ethereum network ID\' CODEC(DoubleDelta, ZSTD(1)),\n    `meta_network_name` LowCardinality(String) COMMENT \'Ethereum network name\',\n    `meta_consensus_version` LowCardinality(String) COMMENT \'Ethereum consensus client version that generated the event\',\n    `meta_consensus_version_major` LowCardinality(String) COMMENT \'Ethereum consensus client major version that generated the event\',\n    `meta_consensus_version_minor` LowCardinality(String) COMMENT \'Ethereum consensus client minor version that generated the event\',\n    `meta_consensus_version_patch` LowCardinality(String) COMMENT \'Ethereum consensus client patch version that generated the event\',\n    `meta_consensus_implementation` LowCardinality(String) COMMENT \'Ethereum consensus client implementation that generated the event\',\n    `meta_labels` Map(String, String) COMMENT \'Labels associated with the event\' CODEC(ZSTD(1))\n)\nENGINE = ReplicatedMergeTree(\'/clickhouse/{installation}/{cluster}/tables/{shard}/default/beacon_api_eth_v1_beacon_blob_local\', \'{replica}\')\nPARTITION BY toStartOfMonth(slot_start_date_time)\nORDER BY (slot_start_date_time, meta_network_name, meta_client_name, block_root, blob_index)\nSETTINGS index_granularity = 8192\nCOMMENT 'Contains beacon API blob metadata derived from block blob_kzg_commitments from each sentry client attached to a beacon node.'\n
